Our global+local shape model is based on the FLAME mesh topology \cite{flame}. We use the FLAME registered D3DFACS \cite{d3dfacs} and CoMA \cite{coma} datasets to compute the local PCA models. The FLAME \cite{flame} model comes with vertex masks corresponding to 14 parts on the human head. We trained individual PCA models corresponding to each of these parts to account for local variations. To do so, we first take FLAME-registered meshes and fit the full FLAME model \cite{flame} to these by optimizing the following fitting loss:
\begin{align}
    L_{fit} = \min_{\beta, \theta, \psi} ||S^{gt} - \Tilde{S}(\beta,\theta,\psi)||,
\end{align}

Here $\Tilde{S}(\beta,\theta,\psi)$ is obtained using ~\cref{eqn:flame,eqn:flame_shape}. We then \textit{unpose} both the ground-truth and the fitted shapes by removing the variations due to pose $\theta$ as described in \cite{flame} and obtain $S^{gt}_0$ and $\Tilde{S}(\beta,0,\psi)$, respectively. The full FLAME model consists of $|\beta|=300$ shapes and $|\psi|=100$ expression bases to account for complete global variations. From this, we retain the top $N_S$ shape and $N_E$ expression bases (based on eigenvalues) and discard the rest to compute shape residuals $\Tilde{S}^{res}=S^{gt}_0 - \Tilde{S}^{coarse}$, where
\begin{align}
    \Tilde{S}^{coarse} = \bar{\mathbf{T}} + \sum_{n=1}^{N_S} \beta_n \mathcal{S}_n + \sum_{n=1}^{N_E} \psi_n \mathcal{E}_n
\end{align}

We then compute the region-wise shape and expression PCA models $(\mathcal{S}^{\mathcal{R}_i}, \mathcal{E}^{\mathcal{R}_i})$ using the region-wise residuals $M_{\mathcal{R}_i}\odot \Tilde{S}^{res}$ (here $M_{\mathcal{R}_i}$ is the vertex-mask for the $i$-th region). For computing the shape bases, we set $N_S=10$ and $N_E=100$ (removing all expression variations); while for the expression bases, we set $N_E=10$ and $N_S=300$ (removing all identity variations). The global + local model can then be represented as,
\begin{small}
\begin{align}
    \label{eqn:global_local_model}
    T(\beta^{\mathcal{G}}, \beta^{\mathcal{R}}, \theta, \psi^{\mathcal{G}}, \psi^{\mathcal{R}})= T_{\mathcal{G}}(\beta^{\mathcal{G}}, \theta, \psi^{\mathcal{G}}) + T_{\mathcal{R}}(\beta^{\mathcal{R}}, \psi^{\mathcal{R}}),
\end{align}
\end{small}

\end{align}
\end{small}
\noindent where $T_{\mathcal{G}}(\beta^{\mathcal{G}}, \theta, \psi^{\mathcal{G}})$ is the coarse global shape given by the top $N_S$ shape and $N_E$ expression global bases, along with the pose blendshapes $\mathcal{P}$ (~\cref{eqn:flame_shape}); and $T_{\mathcal{R}}(\beta^{\mathcal{R}}, \psi^{\mathcal{R}})$ represent the local variations and is given by,
\begin{small}
\begin{align}
    \label{eqn:region_wise_shape}
    \tiny
    T_{\mathcal{R}}(\beta^{\mathcal{R}}, \psi^{\mathcal{R}}) = \sum_{\mathcal{R}_i} \left( \sum_{n=1}^{|\beta^{\mathcal{R}_i}|} \beta^{\mathcal{R}_i}_n \mathcal{S}^{\mathcal{R}_i}_n + \sum_{n=1}^{|\psi^{\mathcal{R}_i}|} \psi^{\mathcal{R}_i}_n \mathcal{E}^{\mathcal{R}_i}_n \right)
\end{align}
\end{small}

\subsection{Shape Completion using Mesh-VAE}
We use the global+local model to fit robust 3D reconstruction on the visible parts of the occluded face. But this does not ensure robust and consistent reconstruction on the occluded parts since the local PCA models have noisy (occluded) or no data to fit to. To address this drawback and to enable the generation of a distribution of plausible 3D reconstructions rather than a singular solution, which is one of our primary goals, we adopt a mesh-based VAE (dubbed \textit{Mesh-VAE}) as our shape completion model.

We assume that human head meshes can be mapped onto a continuous and regularized low-dimensional latent space $\mathcal{Z}$. Then, given a partial 3D mesh $\mathbf{S}_m$, the Mesh-VAE learns the conditional likelihood of mesh completions $\mathbf{S}_c$ and the corresponding latent embeddings $\mathbf{z}$:
\begin{align}
    p(\mathbf{S}_c, \mathbf{z} | \mathbf{S}_m) = p(\mathbf{z} | \mathbf{S}_m) p(\mathbf{S}_c | \mathbf{z}, \mathbf{S}_m),
\end{align}

We adopt the quality-diversity based formulation of the DPP kernel $\mathbf{L}$ \cite{dpp}, which seeks to balance the quality of samples with their diversity. Specifically, for elements $i, j$ in a set, its kernel entry is given by $L_{i,j}=q_iS_{i,j}q_j$, where $q_i$ denotes the quality of element $i$, and $S_{i,j}$ represents the similarity between $i$ and $j$. Maximizing the determinant of such a kernel matrix implies maximizing the quality of each sample while minimizing the similarity between distinct samples. For two shape completions $\mathbf{S}_c^i$ and $\mathbf{S}_c^j$, we define the similarity as
\begin{align}
    S_{i,j} = \exp \left(- \frac{k}{\median_{i,j}( dist_{i,j} )} dist_{i,j} \right),
\end{align}
where $dist_{i,j} = ||\mathbf{S}_c^i - \mathbf{S}_c^j||_2$ is the $\ell_2$ distance between the $i$-th and $j$-th shape completions and $k$ is a scaling factor. To ensure that the completed samples look realistic, we relate the quality of a sample with the probability of its latent embedding $\mathbf{z}_i$ lying within 3$\sigma$ of the prior $\mathcal{N}(\boldsymbol{0, I})$ as:
\begin{align}

\begin{align}
    q_i = \exp(- \max(0, \mathbf{z}_i^T\mathbf{z}_i - 3\sqrt{d})),
\end{align}
where $d$ is the dimensionality of $\mathbf{z}_i$. For numerical stability \cite{yuan2019diverse}, we adopt expected cardinality of $\mathbf{L}$ as the DPP loss:
\begin{align}
    \label{eqn:dpp}
    L_{dpp} = - tr \left( \mathbf{I} - (\mathbf{L} + \mathbf{I})^{-1} \right)
\end{align}

\noindent \textbf{Step 1} \textit{Partial Shape Fitting:} In this stage, we first fit our global + local PCA model on the visible parts of the face image $\mathbf{I}_m$ to obtain a partial reconstruction $\mathbf{S}_m$. We employ the following fitting loss:
\begin{align}
    \label{eqn:fitting}
    L_{fitting} = \lambda_1^f L_{lmk} + \lambda_2^f L_{pho} + \lambda_3^f L_{reg},
\end{align}

L_{fitting} = \lambda_1^f L_{lmk} + \lambda_2^f L_{pho} + \lambda_3^f L_{reg},
\end{align}
where $L_{lmk}$ is the landmark loss, $L_{pho}$ is the photometric loss and $L_{reg}$ applies $\ell_2$-regularization over the model parameters. We use an off-the-shelf landmark detector HRNET \cite{hrnet} to detect 68 landmarks on the face along with their confidence values. We mark those landmarks as visible whose confidence exceeds a threshold $\tau$ (set to 0.2) and apply the landmark loss on those points. To add local details, we apply a photometric loss between the input image and a rendered image $\mathbf{I}_{ren}=\mathcal{R}(\mathbf{S}_m, B_{tex}(\gamma, \mathcal{T}), c)$, where $B_{tex}(\gamma, \mathcal{T})$ is the estimated texture and $c$ the estimated camera parameters. We restrict the photometric loss to the visible face region using the face mask $M_f$ and the occlusion mask $M_o$:
\begin{align}
    \label{eqn:photometric}
    L_{pho} = ||(\mathbf{I}_m - \mathbf{I}_{ren})\odot M_f \odot (\mathbf{1}-M_o)||_1
\end{align}

\noindent \textbf{Step 3} \textit{Diversity Promoting Shape Completion:} In this stage, we perform a diversity promoting iterative shape completion routine, which forces the latent embeddings towards diverse modes w.r.t the occluded regions while remaining faithful to the visible regions. At each iteration, we obtain a distribution of shape completions using the decoder $\mathbf{S}_c^j=\mathcal{D}_{mesh}(\mathbf{z}_j), \forall j=1...M$, and update the $\mathbf{z}$'s to minimize a diversity loss:
\begin{align}
    \label{eqn:diversity}
    L_{diversity} = \lambda_1 L_S + \lambda_2 L_{pho} + \lambda_3 L_{dpp}
\end{align}
Here $L_S$ is the shape consistency loss defined as the $\ell_1$-norm between the $\mathbf{S}_c^j$'s and $\mathbf{S}_m$ applied on the visible vertices, $L_{pho}$ is the photometric loss (\cref{eqn:photometric}) and $L_{dpp}$ is the DPP loss (\cref{eqn:dpp}). The loss coefficients are set to have similar magnitude for all the loss components.

We outline the full steps for partial shape fitting and diversification in ~\cref{alg:fitting} and ~\cref{alg:diversity}, respectively.

\begin{algorithm}
\caption{Shape Fitting on the Visible Face Regions}\label{alg:fitting}
\textbf{Input:} Image $\mathbf{I}_m$, Occlusion mask $M_o$, Face mask $\mathbf{M}_f$, Global models $\mathcal{S}, \mathcal{E}, \mathcal{P}$, Local models $\mathcal{S}^{\mathcal{R}_i}$, $\mathcal{E}^{\mathcal{R}_i}$ for $i=1\text{ to }14$, Texture model $\mathcal{T}$, Landmarks detector $\mathcal{H}$\\
\textbf{Parameters:} $\beta, \theta, \psi, \gamma, c, \beta^{\mathcal{R}_i}, \psi^{\mathcal{R}_i}$ for $i=1\text{ to }14$\\
\textbf{Hyperparameters:} $\tau=0.1, n_{iter}, \lambda_1^f, \lambda_2^f, \lambda_3^f, \eta$\\
\textbf{Output:} Partially fitted shape $\mathbf{S}_m$
\begin{algorithmic}
\State Detect landmarks from image  $\mathbf{L}_I, \mathbf{L}_{conf} \gets \mathcal{H}(\mathbf{I}_m)$
\State Set $\mathbf{L}_{valid} \gets 1 \text{ when } \mathbf{L}_{conf} > \tau$ else 0

\State Update $p \gets p - \eta \nabla_p L_{fitting}$ for $p \in \beta, \theta, \psi, \gamma, c,  \beta^{\mathcal{R}_i}, \psi^{\mathcal{R}_i}$ for $i=1\text{ to }14$
\EndFor
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{Diverse Shape Completions}\label{alg:diversity}
\textbf{Input:} Mesh-VAE Encoder $\mathcal{E}_{mesh}$ and Decoder $\mathcal{D}_{mesh}$; From~\cref{alg:fitting}: $\mathbf{I}_m, M_o, \mathbf{M}_f, \mathbf{L}_I, \mathbf{L}_{valid}, \theta, \gamma, c, \mathcal{T}$\\
\textbf{Hyperparameters:} $n_{comp}, \lambda_1, \lambda_2, \lambda_3, \eta$\\
\textbf{Output:} $M$ Shape completions $\{\mathbf{S}_{c}^{j=1:M}\}$
\begin{algorithmic}
\State Sample the vertex mask $M_o^v$ by projecting $\mathbf{S}$ onto $M_o$
\State Obtain latent parameters $\boldsymbol{\mu, \sigma} \gets \mathcal{E}_{mesh}(\mathbf{S}_m \odot M_o^v)$
\State Sample $M$ latent vectors $\mathbf{z}_1,...,\mathbf{z}_M \sim \mathcal{N}(\boldsymbol{\mu, \sigma^2I})$
\For{$i=1$ to $n_{comp}$}

\State $L_{diversity} = \lambda_1 L_{S} + \lambda_2 L_{pho} + \lambda_3 L_{dpp}$
\State Update $\mathbf{z}_j \gets \mathbf{z}_j - \eta \nabla_{\mathbf{z}_j} L_{diversity}$ for $j=1\text{ to }M$
\EndFor
\end{algorithmic}
\end{algorithm}

